import re
import subprocess
def ping_host(hostname):
    if not re.fullmatch(r"[A-Za-z0-9.-]+", hostname) or hostname.startswith("-"):
        raise ValueError("invalid hostname")
    subprocess.run(["ping", "-c", "1", hostname], check=False)

